<script setup lang="ts">
import {computed} from 'vue'
import {mapStatus} from './map-recommendation'
interface Shop {shopId:number;name:string;address:string;qualification:string;status:string;metres:number|null;seconds:number|null;calculatedAt:string|null;mock:boolean}
const props=defineProps<{rows:Shop[];selectedShopId?:number;busy?:boolean;preview?:boolean;complete?:boolean;page?:number;total?:number;expiresAt?:string}>()
const emit=defineEmits<{choose:[id:number];page:[page:number]}>()
const selected=computed(()=>props.rows.find(row=>row.shopId===props.selectedShopId))
const expired=computed(()=>Boolean(props.expiresAt&&new Date(props.expiresAt).getTime()<=Date.now()))
function selectable(row:Shop){return !props.busy&&!expired.value&&row.status==='READY'}
function choose(row:Shop){if(selectable(row))emit('choose',row.shopId)}
</script>
<template>
 <p v-if="expired" class="candidate-warning" role="alert">本次推荐已过期，请重新查询后再选择；不会自动重算。</p>
 <div v-if="!rows.length" class="candidate-empty" role="status"><span aria-hidden="true">⌖</span><strong>暂无可选择的推荐网点</strong><p>先确认停车位置，再查询候选；无匹配时请核对网点服务区域、车型及位置资料。</p></div>
 <div v-else class="candidate-scroll"><table class="candidate-table"><thead><tr><th>选择</th><th>合作网点</th><th>{{ preview?'模拟排序数值':'驾车道路距离' }}</th><th>预计时间</th></tr></thead><tbody><tr v-for="(item,index) in rows" :key="item.shopId" :class="{chosen:selectedShopId===item.shopId}"><td><input type="radio" name="recommended-shop" :aria-label="'选择'+item.name" :checked="selectedShopId===item.shopId" :disabled="!selectable(item)" @change="choose(item)"></td><td><label class="shop-name"><span class="rank">{{ ((page??1)-1)*20+index+1 }}</span>{{ item.name }}<span v-if="index===0&&(page??1)===1&&item.metres!=null&&item.status==='READY'" class="nearest">{{ complete?'距离推荐':'已知结果' }}</span></label><p>{{ item.address }}</p><small>{{ item.qualification }}</small><small class="row-status">{{ preview?'合成结果，仅验证交互':mapStatus(item.status) }}<template v-if="item.calculatedAt"> · {{ new Date(item.calculatedAt).toLocaleString() }}</template></small></td><td><strong>{{ item.metres==null?'未知':(item.metres/1000).toFixed(2)+' km' }}</strong><small>{{ preview?'非真实道路距离':item.mock?'Mock，非真实道路距离':item.metres==null?'未取得道路距离':'道路规划距离' }}</small></td><td>{{ item.seconds==null?'—':'约'+Math.ceil(item.seconds/60)+'分钟' }}</td></tr></tbody></table></div>
 <div v-if="(total??0)>20" class="candidate-pagination"><button type="button" :disabled="busy||(page??1)<=1" @click="emit('page',(page??1)-1)">上一页</button><span>第{{ page??1 }}页 · 共{{ total }}个</span><button type="button" :disabled="busy||(page??1)*20>=(total??0)" @click="emit('page',(page??1)+1)">下一页</button></div>
 <p v-if="selected" class="selection-summary" role="status">已选择：<strong>{{ selected.name }}</strong>。{{ preview?'仅为模拟选择，不会提交正式派单。':'核对后点击下方原派单按钮；选择网点不会自动提交。' }}</p>
</template>
<style scoped>
.candidate-scroll{overflow-x:auto}.candidate-table{width:100%;border-collapse:collapse;font-size:13px}.candidate-table th{text-align:left;background:#f5f7f6;font-size:12px;color:#66766d;font-weight:500;white-space:nowrap}.candidate-table th,.candidate-table td{padding:14px 10px;border-bottom:1px solid #e5ebe7;vertical-align:top}.candidate-table td:first-child{width:35px;padding-top:20px}.candidate-table input{accent-color:#315e48;width:17px;height:17px}.candidate-table td:nth-child(3){min-width:100px}.candidate-table td:last-child{min-width:75px}.shop-name{font-weight:600;display:flex;align-items:center;gap:6px;flex-wrap:wrap}.rank{background:#edf2ef;color:#4d6759;padding:2px 5px;border-radius:4px;font-size:11px}.nearest{color:#2e7052;background:#e8f4ed;border-radius:4px;padding:2px 6px;font-size:10px;white-space:nowrap}.candidate-table p{margin:7px 0;color:#66766d;line-height:1.5}.candidate-table small{display:block;color:#718078;line-height:1.6;font-size:11px}.candidate-table .chosen{background:#f0f7f2}.row-status{margin-top:4px}.candidate-empty{text-align:center;padding:30px 15px;color:#718078;background:#fafcfb;border:1px dashed #dce5df;border-radius:9px}.candidate-empty>span{font-size:32px;display:block;color:#a5b6aa}.candidate-empty strong{display:block;margin-top:7px;font-size:14px}.candidate-empty p{font-size:12px;line-height:1.8;margin-bottom:0}.selection-summary{padding:12px 14px;background:#f0f6f2;color:#325942;border-radius:7px;font-size:13px;line-height:1.6}.candidate-pagination{display:flex;align-items:center;gap:10px;margin-top:14px;font-size:12px}.candidate-warning{padding:10px;background:#fff7e8;color:#815918;border-radius:6px}
</style>
